const voiceCards = $('Fetch Active Voice Cards').first().json.records;
const insights = $('Fetch Insights Last 24h').first().json.records;

const pairs = [];
for (const card of voiceCards) {
  const cardAudienceTags = (card.fields.audience_tags || []).map(t => t.toLowerCase());
  const matchedInsights = insights
    .filter(ins => {
      const insTags = (ins.fields.audience_segment || []).map(t => t.toLowerCase());
      return insTags.some(t => cardAudienceTags.includes(t));
    })
    .sort((a, b) => (b.fields.intent_level || 0) - (a.fields.intent_level || 0))
    .slice(0, 5);
  pairs.push({
    json: {
      voice_card_id: card.id,
      voice_card: card.fields,
      insights: matchedInsights.map(i => ({
        id: i.id,
        raw_text: i.fields.raw_text,
        topic_tag: i.fields.topic_tag,
        intent_level: i.fields.intent_level,
      })),
    },
  });
}
return pairs;

