const raw = $input.first().json.content?.[0]?.text || '';
const card = $('Loop 3 cards in parallel').first().json.voice_card;
const voiceCardId = $('Loop 3 cards in parallel').first().json.voice_card_id;

let parsed;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m[0]);
} catch (e) {
  return [{ json: { error: 'parse_failed', raw, voice_card_id: voiceCardId } }];
}

const forbidden = (card.forbidden_words || '').toLowerCase().split(/[,\n]/).map(w => w.trim()).filter(Boolean);
const verified = (card.verified_claims_only ?? true);

const checked = (parsed.ideas || []).map((idea, idx) => {
  const full = (idea.title + ' ' + idea.body + ' ' + idea.cta).toLowerCase();
  const violations = [];
  for (const w of forbidden) if (w && full.includes(w)) violations.push('forbidden_word:' + w);
  const limits = { text: 1300, carousel: 1300, reel: 800, blog: 8000 };
  if ((idea.body || '').length > (limits[idea.format] || 1300)) violations.push('length_exceeded');
  const claimPat = /(\d+(\.\d+)?%|top \d|số 1|nhất|duy nhất|đầu tiên|cam kết \d+)/i;
  if (verified && claimPat.test(full)) violations.push('unverified_claim');
  if (!idea.cta || idea.cta.length < 5) violations.push('missing_cta');
  const childPat = /(bé tên|con anh|con chị|học sinh tên|cháu tên)/i;
  const childFlag = childPat.test(full);
  return { ...idea, idx, violations, passed_hard_rules: violations.length === 0, requires_consent_check: childFlag };
});

return [{
  json: {
    voice_card_id: voiceCardId,
    voice_card: card,
    ideas: checked,
    passed_ideas: checked.filter(i => i.passed_hard_rules),
  },
}];

