const raw = $input.first().json.content?.[0]?.text || '';
const prev = $('Parse + Hard Rules').first().json;

let scored = [];
try {
  const m = raw.match(/\{[\s\S]*\}/);
  scored = JSON.parse(m[0]).scores || [];
} catch (e) {}

const byIdx = new Map(scored.map(s => [s.idx, s]));
const ranked = prev.passed_ideas
  .map(i => ({ ...i, score: byIdx.get(i.idx) || { total: 0 } }))
  .sort((a, b) => (b.score.total || 0) - (a.score.total || 0));

const best = ranked[0];
const tier = String(prev.voice_card.channel_tier);

// Routing — KHÔNG có tier 1 auto. Tất cả route to needs_assets (trừ tier 3 → ekip shoot)
let route, status;
if (tier === '3') {
  route = 'tier3_ekip_shoot';
  status = 'needs_shoot';
} else {
  // tier 1, 2, 2.5 — tất cả đều cần asset gen + duyệt sáng
  route = 'tier' + tier + '_pre_approval';
  status = best.video_engine && best.video_engine !== 'none' ? 'needs_video' : (best.format === 'carousel' || best.format === 'blog' ? 'needs_image' : 'needs_text_only');
}

const now = new Date();
const utm_campaign = now.toISOString().slice(0,10) + '-' + (prev.voice_card.channel_name || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '-');
const utm_content = 'auto-' + now.getTime() + '-' + Math.random().toString(36).slice(2, 8);
const utm_suffix = '?utm_source=' + (prev.voice_card.platforms||[''])[0] + '&utm_medium=organic&utm_campaign=' + utm_campaign + '&utm_content=' + utm_content;

return [{
  json: {
    voice_card_id: prev.voice_card_id,
    voice_card: prev.voice_card,
    best_idea: best,
    route,
    status,
    utm_campaign,
    utm_content,
    cta_url_with_utm: (prev.voice_card.cta_url || '') + utm_suffix,
    score_total: best.score.total,
    score_breakdown: best.score,
  },
}];

